from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(19,'proportionnalite','La proportionnalité','5 · Modéliser et organiser',
'Deux grandeurs · Fois plus · Fois moins',
['Reconnaître une situation de proportionnalité.','Raisonner avec « fois plus » et « fois moins ».','Résoudre des problèmes de proportionnalité en contexte.'],
['Multiplication, division et nombres décimaux.'],[
page(1,'Reconnaître une situation proportionnelle',
bloc('definition',r'Deux grandeurs sont en situation de proportionnalité quand, si l’une est multipliée par un nombre, l’autre est multipliée par le même nombre : 2 fois plus de baguettes, 2 fois plus cher ; 3 fois moins de farine, 3 fois moins de crêpes.'),
bloc('exemple',r'Le prix de cahiers identiques est proportionnel à leur nombre. En revanche, la taille d’un enfant n’est pas proportionnelle à son âge : à 10 ans, on ne mesure pas deux fois sa taille de 5 ans.'),
bloc('attention',r'Un prix avec une part fixe n’est pas proportionnel : avec 10 euros d’abonnement puis 2 euros par séance, 10 séances ne coûtent pas deux fois plus que 5 séances. Vérifier le « fois plus » avant de l’utiliser.'),
bloc('savoirfaire',r'Rédiger le raisonnement avec une phrase : « Si j’achète 3 fois plus de pains, alors je paie 3 fois plus. » La phrase dit la grandeur, le sens et le nombre de fois.','Dire le raisonnement')),
page(2,'Raisonner de proportion en proportion',
bloc('exemple',r'Quatre pains aux raisins coûtent 7 euros. Douze pains, c’est 3 fois plus de pains : ils coûtent 3 fois plus, soit $7\times3=21$ euros. Le prix d’un seul pain n’était pas nécessaire.'),
bloc('savoirfaire',r'« Fois moins » fonctionne de même : si 10 photocopies coûtent 3 euros, 5 photocopies, c’est 2 fois moins, donc $3:2=1{,}50$ euro. Chercher le lien multiplicatif entre les deux quantités données.','Multiplier ou diviser les deux grandeurs'),
bloc('exemple',r'Une fontaine régulière remplit 40 L en 5 min. En 20 min, soit 4 fois plus de temps, elle remplit $40\times4=160$ L. Le débit régulier garantit la proportionnalité.'),
bloc('attention',r'Toujours contrôler la vraisemblance : plus de pains doit coûter plus cher ; moins de temps doit donner moins d’eau. Un résultat qui diminue quand la quantité augmente signale une erreur.'))
],[
E('Proportionnel ou pas ?',r'Dire si chaque situation relève de la proportionnalité : le prix de cahiers identiques selon leur nombre ; la taille d’un enfant selon son âge.',r'Les cahiers : $\res{\text{oui}}$, 2 fois plus de cahiers coûtent 2 fois plus. La taille : $\res{\text{non}}$, elle n’est pas multipliée par 2 quand l’âge double.','Tester la phrase « fois plus » sur la situation.','assert 2*2==4'),
E('Deux fois plus',r'Un kilogramme de pommes coûte $2{,}40$ euros. Combien coûtent 2 kg, puis 4 kg ?',r'2 kg, c’est 2 fois plus : $2{,}40\times2=\res{4{,}80}$ euros. 4 kg, c’est encore le double : $\res{9{,}60}$ euros.','Doubler le prix quand la masse double.','assert Rational("2.40")*2==Rational("4.80") and Rational("4.80")*2==Rational("9.60")'),
E('La recette multipliée',r'Pour 4 personnes, une recette demande 250 g de riz. Quelle masse pour 8 personnes ? Pour 12 personnes ?',r'8 personnes, 2 fois plus : $250\times2=\res{500}$ g. 12 personnes, 3 fois plus que 4 : $250\times3=\res{750}$ g.','Comparer les nombres de personnes entre eux.','assert 250*2==500 and 250*3==750'),
E('Les pains aux raisins',r'Quatre pains aux raisins coûtent 7 euros. Combien coûtent 12 pains aux raisins ?',r'12 pains, c’est $12:4=3$ fois plus de pains : ils coûtent 3 fois plus, soit $7\times3=\res{21}$ euros. Inutile de connaître le prix d’un pain.','Chercher le lien multiplicatif entre 4 et 12.','assert 12//4==3 and 7*3==21'),
E('Les cahiers du bureau',r'Cinq cahiers identiques coûtent 8 euros. Combien coûtent 15 cahiers ?',r'15 cahiers, c’est 3 fois plus : $8\times3=\res{24}$ euros.','Multiplier le prix par le même nombre de fois.','assert 15//5==3 and 8*3==24'),
E('Fois moins',r'Dix photocopies coûtent 3 euros. Combien coûtent 30 photocopies ? Et 5 photocopies ?',r'30 copies, 3 fois plus : $3\times3=\res9$ euros. 5 copies, 2 fois moins que 10 : $3:2=\res{1{,}50}$ euro.','Utiliser « fois plus » et « fois moins » depuis la même donnée.','assert 3*3==9 and Rational(3,2)==Rational("1.50")'),
E('Le pot de peinture',r'Six litres de peinture couvrent 30 m² de mur. Quelle surface couvrent 3 litres ? Et 18 litres ?',r'3 L, 2 fois moins : $30:2=\res{15}$ m². 18 L, 3 fois plus que 6 : $30\times3=\res{90}$ m².','Relier chaque quantité de peinture à 6 litres.','assert 30//2==15 and 30*3==90'),
E('À allure régulière',r'Un train roule à allure régulière : en 2 heures, il parcourt 320 km.'+Q(r'Quelle distance parcourt-il en 1 heure ?',r'Quelle distance parcourt-il en 6 heures ?'),r'1 h, 2 fois moins de temps : $320:2=\res{160}$ km. 6 h, 3 fois plus que 2 h : $320\times3=\res{960}$ km. L’allure régulière rend la distance proportionnelle au temps.','Comparer chaque durée à 2 heures.','assert 320//2==160 and 320*3==960'),
E('Les crêpes du goûter',r'Avec 250 g de farine, on fait 12 crêpes. Combien de crêpes avec 500 g ? Quelle farine pour 36 crêpes ?',r'500 g, 2 fois plus : $12\times2=\res{24}$ crêpes. 36 crêpes, 3 fois plus que 12 : $250\times3=\res{750}$ g de farine.','Raisonner dans le sens demandé par chaque question.','assert 12*2==24 and 36//12==3 and 250*3==750'),
E('L’abonnement piégé',r'La piscine coûte 10 euros d’abonnement puis 2 euros par entrée. Paul dit : « 10 entrées coûtent deux fois plus cher que 5 entrées. » Vérifier.',r'5 entrées : $10+5\times2=20$ euros. 10 entrées : $10+10\times2=30$ euros. Or $20\times2=40\ne30$ : Paul $\res{\text{se trompe}}$, la part fixe de l’abonnement casse la proportionnalité.','Calculer les deux montants avant de comparer.','assert 10+5*2==20 and 10+10*2==30 and 30!=40'),
E('La fontaine du square',r'Une fontaine au débit régulier remplit un arrosoir de 40 L en 5 minutes. Quel volume remplit-elle en 20 minutes ? En combien de temps remplit-elle 120 L ?',r'20 min, 4 fois plus : $40\times4=\res{160}$ L. Pour 120 L, soit 3 fois 40 L, il faut 3 fois plus de temps : $5\times3=\res{15}$ min.','Faire le lien multiplicatif sur la grandeur connue.','assert 40*4==160 and 120//40==3 and 5*3==15'),
E('Le marché',r'Trois kilogrammes de poires coûtent $7{,}50$ euros. Combien coûtent 9 kg ? Et 6 kg ?',r'9 kg, 3 fois plus : $7{,}50\times3=\res{22{,}50}$ euros. 6 kg, 2 fois plus : $7{,}50\times2=\res{15}$ euros.','Relier chaque masse à 3 kg.','assert Rational("7.50")*3==Rational("22.50") and Rational("7.50")*2==15'),
E('Deux boulangeries',r'Chez Bleuet, 4 croissants coûtent 5 euros. Chez Coquelicot, 8 croissants coûtent $9{,}60$ euros. Où 8 croissants sont-ils les moins chers ?',r'Chez Bleuet, 8 croissants, 2 fois plus : $5\times2=10$ euros. Chez Coquelicot : $9{,}60$ euros. Comme $9{,}60<10$, c’est $\res{\text{chez Coquelicot}}$, avec $0{,}40$ euro d’écart.','Ramener les deux offres au même nombre de croissants.','assert 5*2==10 and Rational("9.60")<10 and 10-Rational("9.60")==Rational(".40")'),
E('Le ruban au mètre',r'Quatre mètres de ruban coûtent 6 euros. Lisa veut 10 m : elle calcule le prix de 2 m, puis multiplie par 5. Détailler et conclure.',r'2 m, 2 fois moins que 4 m : $6:2=3$ euros. 10 m, 5 fois plus que 2 m : $3\times5=\res{15}$ euros. Passer par 2 m permet d’atteindre 10 m par multiplication.','Enchaîner un « fois moins » puis un « fois plus ».','assert 6//2==3 and 3*5==15 and 10==2*5'),
E('Le carré qui grandit',r'On double le côté d’un carré. Son périmètre double-t-il ? Son aire double-t-elle ? Tester avec un carré de 3 carreaux de côté.',r'Périmètre : $4\times3=12$ devient $4\times6=24$ : il $\res{\text{double}}$, le périmètre est proportionnel au côté. Aire : $3\times3=9$ carreaux devient $6\times6=36$ : elle est multipliée par $\res4$, pas par 2 : l’aire n’est pas proportionnelle au côté.','Tester chaque grandeur séparément.','assert 4*3==12 and 4*6==24 and 24==2*12 and 3*3==9 and 6*6==36 and 36==4*9')
],reperes=['Reconnaître la proportionnalité','Fois plus et fois moins','Situations régulières','Pièges et comparaisons'],deco='courbe')

chapitre(20,'donnees','Organiser et lire des données','5 · Modéliser et organiser',
'Tableaux · Diagrammes en barres · Courbes',
['Recueillir des données et les ranger dans un tableau.','Lire un tableau, un diagramme en barres ou une courbe.','Résoudre des problèmes à partir de données organisées.'],
['Lecture de graduations et opérations sur les entiers.'],[
page(1,'Les tableaux',
bloc('definition',r'Un tableau range des données pour les retrouver vite. Dans un tableau à double entrée, une case se lit au croisement d’une ligne et d’une colonne : elle répond à deux questions à la fois.'),
bloc('exemple',r'Une enquête commence par une question (« Quel est ton fruit préféré ? »), continue par un recueil des réponses, puis par un comptage des effectifs : le tableau présente le résultat.')+
tableau(['Fruit','pomme','fraise','cerise','banane'],[['Effectif','7','9','5','4']]),
bloc('savoirfaire',r'Contrôler un tableau d’enquête : la somme des effectifs doit retrouver le nombre de réponses. Ici $7+9+5+4=25$ élèves interrogés.','Contrôler les totaux')),
page(2,'Diagrammes et courbes',
bloc('definition',r'Dans un diagramme en barres, la hauteur de chaque barre représente un effectif, lu sur l’axe gradué. Dans une courbe, chaque point donne la valeur d’une grandeur à un instant : la ligne montre l’évolution.'),
r'@FIG:cours-donnees@',
bloc('savoirfaire',r'Avant de lire : repérer le titre, les grandeurs des deux axes et le pas des graduations. Un carreau ne vaut pas toujours 1 : il peut valoir 2, 5, 10 ou plus.','Lire les axes d’abord'),
bloc('attention',r'Les données réelles, par exemple des températures ou des précipitations, se lisent avec prudence : la courbe relie des mesures, elle ne dit rien d’exact entre deux points mesurés.'))
],[
E('Lire un tableau',r'Le tableau du cours donne les fruits préférés de la classe. Combien d’élèves préfèrent la fraise ? Combien d’élèves ont répondu en tout ?',r'La colonne fraise indique $\res9$ élèves. Le total vaut $7+9+5+4=\res{25}$ élèves.','Lire la bonne colonne puis additionner.','assert 7+9+5+4==25'),
E('Double entrée',r'Le tableau croise deux classes et deux menus.'+tableau(['','Menu A','Menu B'],[['CM1','17','8'],['CM2','14','12']])+r'Combien d’élèves de CM2 prennent le menu A ? Combien d’élèves prennent le menu B ?',r'Au croisement de la ligne CM2 et de la colonne Menu A : $\res{14}$ élèves. Menu B : $8+12=\res{20}$ élèves.','Croiser ligne et colonne avant d’additionner.','assert 14==14 and 8+12==20'),
E('Compléter les totaux',r'Reprendre le tableau des menus et calculer : le nombre d’élèves de CM1, le nombre d’élèves de CM2 et le nombre total d’élèves.',r'CM1 : $17+8=\res{25}$. CM2 : $14+12=\res{26}$. Total : $25+26=\res{51}$ élèves ; on retrouve ce total en additionnant les colonnes : $31+20=51$.','Vérifier le total par lignes puis par colonnes.','assert 17+8==25 and 14+12==26 and 25+26==51 and 17+14+8+12==51'),
E('Le diagramme en barres',r'Le diagramme donne le nombre de livres empruntés par jour. Lire le nombre de livres du mardi et celui du jeudi. Quel jour en compte le plus ?',r'Mardi : $\res{12}$ livres ; jeudi : $\res{18}$ livres, la barre la plus haute : c’est le $\res{\text{jeudi}}$. Chaque graduation vaut 2 livres.','Lire la hauteur de chaque barre sur l’axe.','assert 18>12',figure='don-4'),
E('La courbe de température',r'La courbe donne la température d’une journée. Lire la température à 8 h et à 14 h. À quelle heure la température est-elle la plus haute ?',r'À 8 h : $\res{12\,^\circ\mathrm C}$ ; à 14 h : $\res{21\,^\circ\mathrm C}$, le point le plus haut de la courbe : le maximum est à $\res{14\ \text h}$.','Suivre la verticale de l’heure jusqu’à la courbe.','assert 21>12',figure='don-5'),
E('Construire un diagramme',r'Construire le diagramme en barres des fruits préférés du cours : pomme 7, fraise 9, cerise 5, banane 4. L’axe est gradué de 1 en 1.',r'Chaque fruit reçoit une barre de la hauteur de son effectif : 7, 9, 5 et 4. La barre la plus haute est celle de la fraise. Le diagramme figure en vert.','Une barre par catégorie, hauteur égale à l’effectif.','assert max([7,9,5,4])==9',figure='don-6'),
E('Des points dans un repère',r'Chaque point du repère donne la masse d’un chiot selon son âge en semaines. Lire la masse à 2 semaines et à 6 semaines.',r'À 2 semaines : $\res{2\ \mathrm{kg}}$. À 6 semaines : $\res{5\ \mathrm{kg}}$. On lit l’abscisse (l’âge) puis l’ordonnée (la masse) de chaque point.','Lire les deux coordonnées dans le bon ordre.','assert 5>2',figure='don-7'),
E('Des questions en étapes',r'Avec le tableau des menus de l’exercice 2 : combien d’élèves de plus en CM2 qu’en CM1 ont choisi le menu B ? Le menu A est-il plus choisi que le menu B ?',r'Menu B : $12-8=\res4$ élèves de plus en CM2. Menu A : $17+14=31$ choix contre 20 : $\res{\text{oui}}$, avec $31-20=11$ choix d’écart.','Extraire les bonnes cases avant de calculer.','assert 12-8==4 and 17+14==31 and 31-20==11'),
E('L’année des températures',r'La courbe donne la température moyenne de chaque mois d’une ville. Quel est le mois le plus chaud ? Le plus froid ? Calculer l’écart entre les deux.',r'Le point le plus haut est en $\res{\text{juillet}}$ ($22\,^\circ$C), le plus bas en $\res{\text{janvier}}$ ($4\,^\circ$C). L’écart vaut $22-4=\res{18}$ degrés.','Chercher les points extrêmes de la courbe.','assert 22-4==18',figure='don-9'),
E('La barre fausse',r'Le tableau annonce : lundi 8, mardi 12, mercredi 6 tickets vendus. Une barre du diagramme ne correspond pas au tableau. Laquelle ? Corriger.',r'La barre du $\res{\text{mardi}}$ monte à 10 au lieu de $\res{12}$. Les barres de lundi et mercredi sont correctes ; la barre corrigée figure en vert.','Comparer chaque barre à sa valeur du tableau.','assert 12!=10',figure='don-10'),
E('L’enquête brute',r'Les réponses brutes à la question « Comment viens-tu à l’école ? » sont : à pied, vélo, à pied, bus, vélo, à pied, bus, à pied, vélo, à pied.'+Q(r'Construire le tableau des effectifs.',r'Quel est le moyen le plus utilisé ?'),r'En comptant : à pied $\res5$, vélo $\res3$, bus $\res2$. Le total $5+3+2=10$ retrouve les dix réponses. Le moyen le plus utilisé est la marche $\res{\text{à pied}}$.','Barrer les réponses au fur et à mesure du comptage.','assert 5+3+2==10 and max([5,3,2])==5'),
E('La bibliothèque',r'Le tableau donne les prêts de la bibliothèque.'+tableau(['','Romans','Documentaires'],[['Semaine 1','34','21'],['Semaine 2','28','25']])+Q(r'Combien de livres ont été prêtés en semaine 1 ?',r'Les prêts de documentaires ont-ils augmenté ou diminué ?',r'Combien de romans ont été prêtés en deux semaines ?'),r'Semaine 1 : $34+21=\res{55}$ prêts. Documentaires : de 21 à 25, ils ont $\res{\text{augmenté}}$ de 4. Romans : $34+28=\res{62}$ en deux semaines.','Choisir les cases utiles à chaque question.','assert 34+21==55 and 25-21==4 and 34+28==62'),
E('La plante qui pousse',r'La courbe donne la hauteur d’une plante semée en classe, mesurée chaque semaine. Lire la hauteur à la semaine 3, puis dire à partir de quelle semaine la plante dépasse 10 cm.',r'À la semaine 3 : $\res{6\ \mathrm{cm}}$. La courbe franchit la ligne des 10 cm entre les semaines 4 et 5 : la plante dépasse 10 cm à partir de la $\res{\text{semaine }5}$, où elle atteint 13 cm.','Suivre la ligne horizontale des 10 cm.','assert 6<10<13',figure='don-13'),
E('Deux villes, deux courbes',r'Le graphique superpose les températures de Brestel et de Lyonnet sur quatre saisons. Quelle ville est la plus chaude en été ? En hiver ? Quelle ville a les températures les plus régulières ?',r'En été, la courbe de Lyonnet est au-dessus : $\res{\text{Lyonnet}}$ ($24\,^\circ$C contre 18). En hiver, Brestel garde $\res{7\,^\circ\mathrm C}$ contre 3. Les variations de Brestel, de 7 à 18 degrés, sont plus resserrées : ses températures sont $\res{\text{les plus régulières}}$.','Comparer les courbes saison par saison.','assert 24>18 and 7>3 and 18-7<24-3',figure='don-14'),
E('Les précipitations',r'Le tableau donne les précipitations d’une ville, en millimètres.'+tableau(['Mois','sept.','oct.','nov.','déc.'],[['Pluie (mm)','45','78','96','60']])+Q(r'Quel mois est le plus pluvieux ?',r'Combien de pluie est tombée en tout sur ces quatre mois ?',r'Novembre a-t-il reçu plus de pluie que septembre et décembre réunis ?'),r'Le mois le plus pluvieux est $\res{\text{novembre}}$ (96 mm). Total : $45+78+96+60=\res{279}$ mm. Septembre et décembre réunis : $45+60=105$ mm ; novembre, avec 96 mm, en a reçu $\res{\text{moins}}$.','Répondre à chaque question avec les bonnes cases.','assert max([45,78,96,60])==96 and 45+78+96+60==279 and 45+60==105 and 96<105')
],reperes=['Tableaux simples et doubles','Diagrammes en barres','Courbes et repères','Enquêtes et données réelles'],deco='statistiques')

chapitre(21,'hasard','Premiers pas vers le hasard','5 · Modéliser et organiser',
'Expériences aléatoires · Issues · Échelle des chances',
['Reconnaître une expérience aléatoire et lister ses issues.','Employer le vocabulaire : certain, possible, impossible, probable.','Comparer les chances de réalisation d’évènements.'],
['Fractions simples et dénombrement.'],[
page(1,'Le vocabulaire du hasard',
bloc('definition',r'Une expérience est aléatoire quand son résultat ne peut pas être prévu avant de la réaliser : lancer un dé, tirer une boule d’un sac sans regarder, piocher une carte. Les résultats possibles s’appellent les issues.'),
bloc('exemple',r'Avec un dé ordinaire : « obtenir 7 » est impossible ; « obtenir un nombre de 1 à 6 » est certain ; « obtenir 2 » est possible, sans certitude. Entre impossible et certain, tous les degrés existent.'),
r'@FIG:cours-echelle@',
bloc('savoirfaire',r'« Une chance sur deux » décrit un évènement qui a autant de chances de se réaliser que de ne pas se réaliser : obtenir pile avec une pièce, ou tirer une carte rouge dans un jeu qui compte autant de rouges que de noires.','Une chance sur deux')),
page(2,'Compter les issues',
bloc('savoirfaire',r'Lister toutes les issues avant de raisonner : une pièce en a 2, un dé en a 6, une urne de 4 boules en a 4. Un évènement est d’autant plus probable qu’il est réalisé par davantage d’issues, quand toutes les issues ont les mêmes chances.','Recenser les issues'),
bloc('definition',r'Quand toutes les issues ont les mêmes chances de sortir, la situation est équiprobable : dé équilibré, boules indiscernables au toucher, cartes bien mélangées.'),
bloc('attention',r'Deux issues possibles ne donnent pas toujours une chance sur deux ! Avec une urne de 1 boule rouge et 3 bleues, « rouge » et « bleu » sont deux résultats possibles, mais le bleu a trois fois plus d’issues pour lui.'),
bloc('exemple',r'Obtenir 6 trois fois de suite n’assure rien pour le lancer suivant : le résultat reste imprévisible, c’est justement une expérience aléatoire.'))
],[
E('Aléatoire ou pas ?',r'Dire si l’expérience est aléatoire : lancer un dé et lire la face ; faire bouillir de l’eau et observer si elle chauffe ; tirer une carte d’un jeu mélangé.',r'Le dé et la carte : $\res{\text{aléatoires}}$, le résultat est imprévisible. L’eau qui chauffe : résultat $\res{\text{certain}}$, l’expérience n’est pas aléatoire.','Se demander si le résultat est prévisible.','assert 1==1'),
E('Le bon mot',r'Avec un dé ordinaire, qualifier chaque évènement : « obtenir 7 » ; « obtenir un nombre de 1 à 6 » ; « obtenir 2 ».',r'« Obtenir 7 » : $\res{\text{impossible}}$. « De 1 à 6 » : $\res{\text{certain}}$. « Obtenir 2 » : $\res{\text{possible}}$, une issue sur six.','Confronter l’évènement à la liste des issues.','assert len([a for a in range(1,7) if a==7])==0 and len([a for a in range(1,7)])==6'),
E('Lister les issues',r'Lister toutes les issues : d’un lancer de pièce ; d’un lancer de dé ; du tirage d’une boule dans un sac contenant une boule rouge, une verte et une bleue.',r'Pièce : $\res{\text{pile, face}}$, 2 issues. Dé : $\res{1,2,3,4,5,6}$, 6 issues. Sac : $\res{\text{rouge, verte, bleue}}$, 3 issues.','Écrire la liste complète sans oubli ni doublon.','assert 2==2 and len([1,2,3,4,5,6])==6 and 3==3'),
E('Une chance sur deux',r'Dire si l’évènement a une chance sur deux de se réaliser : obtenir pile avec une pièce ; obtenir un nombre pair avec un dé ; tirer une carte rouge d’un jeu de 32 cartes bien mélangé.',r'Pile : $\res{\text{oui}}$, une issue sur deux. Pair : les issues 2, 4, 6 sur six, soit la moitié : $\res{\text{oui}}$. Carte rouge : 16 rouges sur 32 : $\res{\text{oui}}$ aussi.','Comparer les issues favorables à la moitié du total.','assert len([a for a in range(1,7) if a%2==0])==3 and Rational(3,6)==Rational(1,2) and Rational(16,32)==Rational(1,2)'),
E('Sur l’échelle des chances',r'Placer chaque évènement sur l’échelle, d’impossible à certain : « janvier suivra décembre » ; « obtenir 3 avec un dé » ; « tirer une boule jaune d’un sac qui n’en contient pas ».',r'Janvier après décembre : $\res{\text{certain}}$, à droite. Obtenir 3 : $\res{\text{peu probable}}$, une issue sur six, à gauche du milieu. La boule jaune : $\res{\text{impossible}}$, tout à gauche. Les positions figurent en vert.','Associer chaque évènement à une zone de l’échelle.','assert Rational(1,6)<Rational(1,2)',figure='pro-5'),
E('Plus ou moins probable',r'Avec un dé équilibré, quel évènement est le plus probable : « obtenir 2 » ou « obtenir un nombre pair » ? Justifier en comptant les issues.',r'« Obtenir 2 » : 1 issue. « Pair » : 3 issues (2, 4, 6). Le pair est $\res{\text{plus probable}}$ : trois fois plus d’issues le réalisent.','Compter les issues qui réalisent chaque évènement.','assert 3>1',figure='pro-6'),
E('L’urne trompeuse',r'Un sac contient 1 boule rouge et 3 boules bleues, indiscernables au toucher. Maé dit : « Rouge ou bleu, il y a deux résultats : j’ai une chance sur deux de tirer rouge. » Corriger.',r'Les issues sont les 4 boules, pas les 2 couleurs : une seule boule donne le rouge, trois donnent le bleu. Le rouge est $\res{\text{peu probable}}$, loin d’une chance sur deux : compter les issues, pas les noms des résultats.','Revenir aux boules, les vraies issues du tirage.','assert 1+3==4 and Rational(1,4)!=Rational(1,2)',figure='pro-7'),
E('Équiprobable ou non ?',r'Dire si toutes les issues ont les mêmes chances : un dé équilibré ; la roue dessinée, aux secteurs de tailles différentes ; une pièce truquée qui retombe presque toujours sur face.',r'Le dé équilibré : $\res{\text{oui}}$, six issues de mêmes chances. La roue aux secteurs inégaux : $\res{\text{non}}$, le grand secteur sort plus souvent. La pièce truquée : $\res{\text{non}}$ plus.','Observer si un résultat est favorisé par l’objet.','assert 1==1',figure='pro-8'),
E('Le sac de la kermesse',r'Un sac contient 5 jetons rouges et 2 jetons bleus. L’évènement « tirer un rouge » est-il probable ou peu probable ? Et « tirer un bleu » ?',r'Cinq issues sur sept donnent le rouge : plus de la moitié, l’évènement est $\res{\text{probable}}$. Le bleu n’a que 2 issues sur 7, moins de la moitié : $\res{\text{peu probable}}$.','Comparer à la moitié du nombre total d’issues.','assert 5+2==7 and Rational(5,7)>Rational(1,2) and Rational(2,7)<Rational(1,2)',figure='pro-9'),
E('Les jetons numérotés',r'Un sac contient huit jetons numérotés de 1 à 8. Quel évènement est le plus probable : « tirer un numéro plus grand que 6 » ou « tirer un numéro plus petit que 4 » ?',r'Plus grand que 6 : les issues 7 et 8, soit 2 issues. Plus petit que 4 : les issues 1, 2 et 3, soit 3 issues. Le second évènement est $\res{\text{plus probable}}$.','Lister les numéros qui réalisent chaque évènement.','assert [a for a in range(1,9) if a>6]==[7,8] and [a for a in range(1,9) if a<4]==[1,2,3] and 3>2'),
E('Le jeu de 32 cartes',r'Dans un jeu de 32 cartes bien mélangé, quel évènement est le plus probable : « tirer un cœur » ou « tirer une carte rouge » ? Justifier.',r'Les cœurs : 8 cartes. Les rouges : les 8 cœurs et les 8 carreaux, 16 cartes. La carte rouge est $\res{\text{plus probable}}$ : tout cœur est déjà une carte rouge, et les carreaux s’y ajoutent.','Compter les cartes qui réalisent chaque évènement.','assert 8<16 and 8+8==16'),
E('Gagner ou perdre',r'À une tombola, Jules dit : « Je gagne ou je perds, donc j’ai une chance sur deux de gagner. » Que lui répondre, sachant que 500 billets sont vendus et que 10 gagnent ?',r'Les issues sont les 500 billets : seuls 10 donnent un lot. Gagner est $\res{\text{peu probable}}$ : deux résultats possibles ne font pas deux résultats de mêmes chances.','Prendre les billets comme issues, pas les mots.','assert Rational(10,500)!=Rational(1,2) and Rational(10,500)<Rational(1,2)'),
E('La roue de la kermesse',r'La roue de la kermesse porte 8 secteurs identiques : 4 marqués « perdu », 3 « bonbon » et 1 « peluche ». Quel lot est le plus probable ? La peluche a-t-elle une chance sur deux de sortir ?',r'Les secteurs identiques rendent les 8 issues équiprobables. « Perdu » : 4 issues, le résultat le plus probable ; « bonbon » : 3 ; « peluche » : $\res1$ issue sur 8, bien moins qu’une chance sur deux : $\res{\text{non}}$.','Compter les secteurs de chaque lot.','assert 4>3>1 and Rational(1,8)<Rational(1,2)',figure='pro-13'),
E('La série de six',r'Nora a obtenu 6 trois fois de suite avec un dé équilibré. Elle affirme : « Je suis sûre d’avoir encore 6 au prochain lancer. » Puis elle se ravise : « Non, le 6 ne peut plus sortir ! » Que penser de ces deux phrases ?',r'Les deux sont fausses : le lancer reste une expérience $\res{\text{aléatoire}}$, au résultat imprévisible. Le 6 reste possible, ni certain ni impossible : les lancers passés ne commandent pas le suivant.','Revenir à la définition d’une expérience aléatoire.','assert 1==1'),
E('Classer quatre évènements',r'On tire une boule d’un sac contenant 2 rouges, 3 vertes et 5 noires. Classer du moins probable au plus probable : « tirer une rouge », « tirer une verte », « tirer une noire », « tirer une boule rouge, verte ou noire ».',r'Les issues : 10 boules. Rouge : 2, verte : 3, noire : 5, et le dernier évènement est réalisé par les 10 : il est $\res{\text{certain}}$. Classement : $\res{\text{rouge}<\text{verte}<\text{noire}<\text{certain}}$.','Compter les issues favorables de chaque évènement.','assert 2<3<5<10 and 2+3+5==10',figure='pro-15')
],reperes=['Expériences et issues','Vocabulaire des chances','Équiprobabilité','Comparer des évènements'],deco='probabilites')
